const post = $json;
const visualRules = `Create a premium editorial technology illustration for a Turkish LinkedIn expert post. Use a sophisticated dark navy, electric blue, white and turquoise palette with selective luminous accents. Build a strong central focal point, layered depth, elegant isometric or semi-3D technical forms, subtle cinematic lighting, soft shadows and crisp geometry. Make complex industrial technology immediately understandable and visually memorable, like a high-end technology magazine cover illustration. Use the full square canvas with balanced negative space. Avoid generic stock imagery, clutter, excessive tiny icons, photorealistic factory scenes, fake dashboard screenshots, customer logos, brand names, human faces and personal data. Do not render any words, letters, labels or pseudo-writing; exact Turkish text and branding will be placed in separate bands outside the illustration. Square 1200x1200 composition.`;
return [{ json: { request_body: {
  model: 'gpt-image-2.5-flare',
  prompt: `${visualRules}\n\nPost theme: ${post.pillar}\nHook: ${post.hook}\nVisual brief: ${post.image_brief}`,
  size: '1200x1200',
  quality: 'high',
  output_format: 'png',
  background: 'opaque'
} } }];

const requestBody = { ...$json.request_body };
requestBody.prompt = `${requestBody.prompt}\n\nPREMIUM ART DIRECTION — this overrides earlier color wording. Match the visual identity of emrecancioglu.com exactly: obsidian black #0A0B0D background, graphite surfaces #131519 and #1A1D22, restrained emerald accent #34D399, deep emerald #10B981, warm off-white #ECECEA and muted gray #9A9A97. Do not use electric blue, cyan, purple, rainbow gradients or excessive neon. Create a luxury enterprise-technology editorial illustration with cinematic low-key lighting, brushed graphite metal, smoked glass, precise micro-details, subtle volumetric depth and controlled emerald reflections. Avoid plastic toy-like 3D icons, generic stock isometric scenes, glossy cartoon objects, oversized shields and decorative glow overload. Show exactly three or four clearly separated architecture components connected by an obvious directional flow. Use recognizable server racks, database cylinders, network zones, gateways, industrial controllers or field devices as appropriate. Reserve clean negative space along the left and right edges for deterministic Turkish callout labels that will be added later. Keep every component visually distinct and do not place important objects against the side edges. The result should feel like a premium technology annual report cover, not a template.`;
return [{ json: { request_body: requestBody } }];

const response = $json;
if (response.error) throw new Error(`OpenAI image error: ${JSON.stringify(response.error)}`);
const base64 = response.data?.[0]?.b64_json;
if (!base64) throw new Error('Gorsel base64 verisi bulunamadi');
const post = $('Select Draft').first().json;
const fileName = `${post.id}.png`;
const imagePath = `/data/content/generated/${fileName}`;
return [{
  json: {
    post_id: post.id,
    image_path: imagePath,
    image_model: 'gpt-image-2.5-flare',
    image_usage: response.usage ?? null
  },
  binary: {
    data: {
      data: base64,
      mimeType: 'image/png',
      fileName,
      fileExtension: 'png'
    }
  }
}];
